const e=JSON.parse('{"key":"v-018723e6","path":"/posts/lesson/cs6.824-distributed-system/lesson4-vmwareFT.html","title":"VMware-FT","lang":"zh-CN","frontmatter":{"category":["分布式系统"],"tag":["分布式系统"],"description":"VMware-FT 1.摘要 2 2.2 VMware-FT 1.摘要 我们已经实现了一个商业企业级系统，用于提供容错虚拟机，该系统基于通过在另一台服务器上的备份虚拟机复制主虚拟机（VM）的执行这一方法。我们在 VMware vSphere 4.0 中设计了一个完整的系统，该系统易于使用，可在商用服务器上运行，并且通常会使实际应用程序的性能降低不到 10%。此外，对于一些实际应用程序，使主虚拟机和辅助虚拟机同步执行所需的数据带宽小于 20 Mbit/s，这使得在更长距离上实现容错成为可能。一个易于使用的商业系统，在故障后自动恢复冗余，除了复制虚拟机执行之外还需要许多额外的组件。我们已经设计并实现了这些额外的组件，并解决了在支持运行企业应用程序的虚拟机时遇到的许多实际问题。在本文中，我们描述了我们的基本设计，讨论了替代设计选择和许多实现细节，并提供了微基准测试和实际应用程序的性能结果。","head":[["meta",{"property":"og:url","content":"https://mister-hope.github.io/posts/lesson/cs6.824-distributed-system/lesson4-vmwareFT.html"}],["meta",{"property":"og:site_name","content":"Code Building"}],["meta",{"property":"og:title","content":"VMware-FT"}],["meta",{"property":"og:description","content":"VMware-FT 1.摘要 2 2.2 VMware-FT 1.摘要 我们已经实现了一个商业企业级系统，用于提供容错虚拟机，该系统基于通过在另一台服务器上的备份虚拟机复制主虚拟机（VM）的执行这一方法。我们在 VMware vSphere 4.0 中设计了一个完整的系统，该系统易于使用，可在商用服务器上运行，并且通常会使实际应用程序的性能降低不到 10%。此外，对于一些实际应用程序，使主虚拟机和辅助虚拟机同步执行所需的数据带宽小于 20 Mbit/s，这使得在更长距离上实现容错成为可能。一个易于使用的商业系统，在故障后自动恢复冗余，除了复制虚拟机执行之外还需要许多额外的组件。我们已经设计并实现了这些额外的组件，并解决了在支持运行企业应用程序的虚拟机时遇到的许多实际问题。在本文中，我们描述了我们的基本设计，讨论了替代设计选择和许多实现细节，并提供了微基准测试和实际应用程序的性能结果。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2024-11-02T13:57:01.000Z"}],["meta",{"property":"article:tag","content":"分布式系统"}],["meta",{"property":"article:modified_time","content":"2024-11-02T13:57:01.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"VMware-FT\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2024-11-02T13:57:01.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"1.摘要","slug":"_1-摘要","link":"#_1-摘要","children":[]},{"level":2,"title":"2","slug":"_2","link":"#_2","children":[{"level":3,"title":"2.2","slug":"_2-2","link":"#_2-2","children":[]}]}],"git":{"createdTime":1730367980000,"updatedTime":1730555821000,"contributors":[{"name":"zgjsxx","email":"119160524@qq.com","commits":2},{"name":"zgjsxx","email":"119160625@qq.com","commits":1}]},"readingTime":{"minutes":6.94,"words":2082},"filePathRelative":"posts/lesson/cs6.824-distributed-system/lesson4-vmwareFT.md","localizedDate":"2024年10月31日","excerpt":"<ul>\\n<li><a href=\\"#vmware-ft\\">VMware-FT</a>\\n<ul>\\n<li><a href=\\"#1%E6%91%98%E8%A6%81\\">1.摘要</a></li>\\n<li><a href=\\"#2\\">2</a>\\n<ul>\\n<li><a href=\\"#22\\">2.2</a></li>\\n</ul>\\n</li>\\n</ul>\\n</li>\\n</ul>\\n<h1> VMware-FT</h1>\\n<h2> 1.摘要</h2>\\n<p>我们已经实现了一个商业企业级系统，用于提供容错虚拟机，该系统基于通过在另一台服务器上的备份虚拟机复制主虚拟机（VM）的执行这一方法。我们在 VMware vSphere 4.0 中设计了一个完整的系统，该系统易于使用，可在商用服务器上运行，并且通常会使实际应用程序的性能降低不到 10%。此外，对于一些实际应用程序，使主虚拟机和辅助虚拟机同步执行所需的数据带宽小于 20 Mbit/s，这使得在更长距离上实现容错成为可能。一个易于使用的商业系统，在故障后自动恢复冗余，除了复制虚拟机执行之外还需要许多额外的组件。我们已经设计并实现了这些额外的组件，并解决了在支持运行企业应用程序的虚拟机时遇到的许多实际问题。在本文中，我们描述了我们的基本设计，讨论了替代设计选择和许多实现细节，并提供了微基准测试和实际应用程序的性能结果。</p>","autoDesc":true}');export{e as data};
